 static string SpriteHash(Bitmap bitmap){using(var memory=new MemoryStream()){bitmap.Save(memory,ImageFormat.Png);using(var sha=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(memory.ToArray()));}}
 static string FixedAreaHash(Bitmap image,float x,float y,float width,float height){using(var region=image.Clone(new Rectangle((int)(image.Width*x),(int)(image.Height*y),(int)(image.Width*width),(int)(image.Height*height)),PixelFormat.Format32bppArgb))return SpriteHash(region);}
 static Rectangle ChangedArea(Bitmap first,Bitmap second,out double centerX){int left=first.Width,top=first.Height,right=-1,bottom=-1,count=0;double sum=0;for(int y=0;y<first.Height;y++)for(int x=0;x<first.Width;x++){var a=first.GetPixel(x,y);var b=second.GetPixel(x,y);if(Math.Abs(a.A-b.A)+Math.Abs(a.R*a.A-b.R*b.A)/255+Math.Abs(a.G*a.A-b.G*b.A)/255+Math.Abs(a.B*a.A-b.B*b.A)/255<20)continue;left=Math.Min(left,x);top=Math.Min(top,y);right=Math.Max(right,x);bottom=Math.Max(bottom,y);count++;sum+=x;}centerX=count==0?double.NaN:sum/count;return count==0?Rectangle.Empty:Rectangle.FromLTRB(left,top,right+1,bottom+1);}
 static Bitmap RenderReading(string style,int tick){var image=new Bitmap(192,192);using(var g=Graphics.FromImage(image))Art.Draw(g,new Rectangle(0,0,192,192),style,"read",tick);return image;}
 static void TestActivities(Controller controller,string folder){
  string preview=Path.Combine(folder,"activity-frames");Directory.CreateDirectory(preview);
  Check(System.Reflection.Assembly.GetExecutingAssembly().GetName().Version.ToString()==AppVersion.Assembly&&System.Diagnostics.FileVersionInfo.GetVersionInfo(Application.ExecutablePath).FileVersion==AppVersion.Assembly,"Release assembly and EXE file versions match the single version source");
  Check(controller.Panel.Text.EndsWith("v"+AppVersion.Current)&&Descendants(controller.Panel).Any(c=>c.Text.Contains("v"+AppVersion.Current)),"Companion center title and navigation use the current release version");
  Check(ActivityArt.Clips.Length==7&&!ActivityArt.Has("stretch")&&ActivityArt.Clips.All(c=>c.Holds.All(h=>h>=50)),"Seven retained actions use deliberate timings and stretching is removed");
  using(var atlas=new Bitmap(320,160)){using(var g=Graphics.FromImage(atlas))foreach(var row in new[]{new Rectangle(0,6,320,39),new Rectangle(0,52,320,34),new Rectangle(0,96,320,31),new Rectangle(0,137,320,17)})g.FillRectangle(Brushes.Purple,row);Check(ActivityArt.RowCuts(atlas).SequenceEqual(new[]{0,48,91,132,160}),"Unequal-height animation rows are separated at transparent gutters so standing feet are not cropped");}
  using(var longRun=new Bitmap(192,192))using(var wrapped=new Bitmap(192,192)){using(var g=Graphics.FromImage(longRun))Art.Draw(g,new Rectangle(0,0,192,192),"anime","working",int.MaxValue);using(var g=Graphics.FromImage(wrapped))Art.Draw(g,new Rectangle(0,0,192,192),"anime","working",int.MaxValue%ActivityArt.Find("working").Duration);Check(SpriteHash(longRun)==SpriteHash(wrapped),"Animation time wraps safely after long-running desktop sessions");}
  foreach(string style in new[]{"pixel","anime"})foreach(var clip in ActivityArt.Clips){
   var frames=Enumerable.Range(0,clip.Holds.Length).Select(i=>ActivityArt.Frame(style,clip.Key,i)).ToArray();Check(frames.All(b=>b!=null)&&frames.Select(b=>b.Size).Distinct().Count()==1,style+" "+clip.Key+" uses a shared canvas throughout the motion");Check(frames.Select(SpriteHash).Distinct().Count()>=(clip.Key=="complete"?1:clip.Key=="rest"?3:6),style+" "+clip.Key+" contains genuine local motion or blink frames");
   Check(frames.Select(b=>FixedAreaHash(b,.27f,0,.46f,clip.Key=="rest"?.25f:.34f)).Distinct().Count()==1,style+" "+clip.Key+" fixes the same head and hair pixels throughout the animation");Check(frames.Select(b=>FixedAreaHash(b,0,.83f,1,.16f)).Distinct().Count()==1,style+" "+clip.Key+" fixes the feet and lower silhouette throughout the animation");Check(frames.Select(b=>FixedAreaHash(b,.41f,.76f,.18f,.04f)).Distinct().Count()==1,style+" "+clip.Key+" fixes the lower torso instead of replacing the whole character");
   if(clip.Key=="read"){
    double rightCenter,leftCenter,unused;float spine=style=="pixel"?82:91;var bookArea=style=="pixel"?new Rectangle(49,93,68,21):new Rectangle(60,98,65,21);
    using(var first=RenderReading(style,0))using(var rightFrame=RenderReading(style,(clip.Holds[0]+50)/50))using(var landed=RenderReading(style,(clip.Duration-250)/50)){
     var right=ChangedArea(first,rightFrame,out rightCenter);var left=ChangedArea(first,landed,out leftCenter);Check(!right.IsEmpty&&rightCenter>spine,style+" page starts on the actual book's right side");Check(!left.IsEmpty&&leftCenter<spine,style+" page finishes on the actual book's left side");bool inside=true;int pageTime=0;for(int n=0;n<8;n++){using(var sample=RenderReading(style,(pageTime+clip.Holds[n]/2)/50)){var changed=ChangedArea(first,sample,out unused);inside&=changed.IsEmpty||bookArea.Contains(changed);}pageTime+=clip.Holds[n];}Check(inside,style+" all page motion remains on the calibrated held book, away from the face");
     string originalHash=SpriteHash(Art.OriginalReading(style));int thoughtTick=(int)(ReadingBook.ThoughtStartsAt+1500)/50;using(var thought=RenderReading(style,thoughtTick))using(var later=RenderReading(style,thoughtTick+20)){Check(SpriteHash(Art.OriginalReading(style))==originalHash,style+" original reading pose is retained without modifying its art");Check(SpriteHash(thought)==SpriteHash(later),style+" original thinking pose stays still during its hold");Check(SpriteHash(thought)!=SpriteHash(first),style+" reading cycle actually displays the original thinking pose");Check(Math.Abs(ActivityArt.OpaqueBounds(thought).Bottom-ActivityArt.OpaqueBounds(first).Bottom)<=1,style+" thinking pose keeps the same foot baseline");}
     Check(Math.Abs(ReadingBook.HeadCenter(ReadingBook.Thought(style))-ReadingBook.HeadCenter(frames[0]))<2,style+" thinking pose is horizontally anchored to the reader's head");
    }
   }
   int elapsed=0;var bottoms=new List<int>();for(int i=0;i<clip.Holds.Length;i++){Check(clip.FrameAt(elapsed)==i&&clip.FrameAt(elapsed+clip.Holds[i]-1)==i,style+" "+clip.Key+" frame "+i+" respects its complete hold interval");using(var bitmap=new Bitmap(192,192)){using(var g=Graphics.FromImage(bitmap))Art.Draw(g,new Rectangle(0,0,192,192),style,clip.Key,(elapsed+clip.Holds[i]/2)/50);var bounds=ActivityArt.OpaqueBounds(bitmap);Check(!bounds.IsEmpty&&bounds.Left>=4&&bounds.Top>=4&&bounds.Right<=188&&bounds.Bottom<=188,style+" "+clip.Key+" frame "+i+" renders inside the pet without clipping");bottoms.Add(bounds.Bottom);bitmap.Save(Path.Combine(preview,style+"-"+clip.Key+"-"+i+".png"),ImageFormat.Png);}elapsed+=clip.Holds[i];}
   Check(clip.FrameAt(clip.Duration)==0,style+" "+clip.Key+" loops back to its first frame");
   File.AppendAllText(Path.Combine(folder,"activity-baselines.txt"),style+" "+clip.Key+": "+string.Join(",",bottoms)+Environment.NewLine);
  }
  foreach(string style in new[]{"pixel","anime"}){string frames=Path.Combine(preview,style);Directory.CreateDirectory(frames);for(int tick=0;tick<120;tick++)using(var canvas=new Bitmap(736,440)){using(var graphics=Graphics.FromImage(canvas)){graphics.Clear(Color.FromArgb(250,247,255));for(int i=0;i<ActivityArt.Clips.Length;i++){var clip=ActivityArt.Clips[i];int col=clip.Group=="daily"?i:i-3;int x=(clip.Group=="daily"?104:12)+col*184,y=clip.Group=="daily"?8:214;Theme.Text(graphics,clip.Name,10,Theme.Ink,new RectangleF(x,y,176,26),true);Art.Draw(graphics,new Rectangle(x,y+24,176,176),style,clip.Key,tick);}Theme.Text(graphics,Theme.Credit,8,Theme.Muted,new RectangleF(12,421,710,18));}canvas.Save(Path.Combine(frames,tick.ToString("000")+".png"),ImageFormat.Png);}}
  long turns=ReadingBook.TurningMilliseconds,thoughtStart=ReadingBook.ThoughtStartsAt;Check(ReadingBook.PagesBeforeThought==3&&!ReadingBook.IsThinking(turns-1)&&!ReadingBook.IsThinking(turns)&&ReadingBook.IsThinking(thoughtStart)&&ReadingBook.IsThinking(thoughtStart+5999)&&!ReadingBook.IsThinking(thoughtStart+6000)&&ReadingBook.FrameAt(ReadingBook.CycleMilliseconds)==0,"Reading turns three pages, transitions to the original pose for six seconds, then transitions back before resuming pages");
  TestReadingRefinements(folder);
  TestActivityRig(folder);
  var director=new IdleActivities(7026);string last="idle";int started=0;var seen=new HashSet<string>();var readingLengths=new List<int>();int begins=0;for(int tick=0;tick<120000;tick++){director.Advance(tick,true);if(director.Pose==last)continue;if(last=="read")readingLengths.Add(tick-started);if(director.Pose!="idle"){Check(director.Pose!="wave"&&director.Pose!="working"&&director.Pose!="waiting"&&director.Pose!="complete"&&director.Pose!="reminder","Random idle action is safe and does not impersonate a task or wave");seen.Add(director.Pose);started=tick;begins++;}last=director.Pose;}
  Check(seen.SetEquals(new[]{"read","tea","rest"})&&readingLengths.All(t=>t>=440&&t<=640),"Random idle rotation includes every daily action and keeps reading for 22–32 seconds");
  director=new IdleActivities(1);var sequence=new List<string>();last="idle";for(int tick=0;tick<10000;tick++){director.Advance(tick,true);if(director.Pose!="idle"&&director.Pose!=last)sequence.Add(director.Pose);last=director.Pose;}Check(sequence.Zip(sequence.Skip(1),(a,b)=>a!=b).All(s=>s),"Random idle actions do not immediately repeat the previous action");director.Advance(10001,false);Check(director.Pose=="idle","Game, drag, movement or task interruption cancels the daily action immediately");for(int tick=10002;tick<15000;tick++)director.Advance(tick,false);Check(director.Pose=="idle","A busy pet cannot start an idle animation");director.Advance(15000,true);Check(director.Pose=="idle","Returning from a task or game does not burst into a stale queued action");
  var random=new Random(332);bool distances=true;for(int i=0;i<1000;i++){var walk=WanderMotion.Offset(random,false);var fly=WanderMotion.Offset(random,true);distances&=Math.Abs(walk.X)>=220&&Math.Abs(walk.X)<=360&&walk.Y==0&&Math.Abs(fly.X)>=260&&Math.Abs(fly.X)<=420&&Math.Abs(fly.Y)>=120&&Math.Abs(fly.Y)<=200;}Check(distances,"Wander routes are longer on foot and diagonally in flight");Check(WanderMotion.MinimumPauseSeconds==35&&WanderMotion.MaximumPauseExclusive==66&&WanderMotion.InitialPauseSeconds==40,"Wander pause frequency remains exactly 35–65 seconds with the original initial delay");
  var fields=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;controller.Pet.StopWalking();var next=(DateTimeOffset)typeof(LayeredPet).GetField("nextMove",fields).GetValue(controller.Pet);Check((next-DateTimeOffset.UtcNow).TotalSeconds>=34.5&&(next-DateTimeOffset.UtcNow).TotalSeconds<=65.1,"The live pet schedules the same rest interval after its longer route");
  controller.Settings.Sound=false;controller.Settings.Quiet=false;controller.SelectGameMode("off");foreach(string kind in new[]{"working","waiting","complete","reminder"}){controller.Receive(new PetEvent{ThreadId="animation-check",Kind=kind,Source="动作检查",Message="检查 "+kind});Check(controller.PoseState==kind&&ActivityArt.Has(controller.PoseState),"A real "+kind+" event selects its dedicated animation");using(var composed=controller.Pet.Compose())composed.Save(Path.Combine(folder,"activity-event-"+kind+".png"),ImageFormat.Png);}controller.Receive(new PetEvent{Kind="complete",Source="番茄钟",Message="休息一下"});Check(controller.State=="complete"&&controller.PoseState=="rest","Pomodoro completion keeps completion semantics while showing the dedicated rest animation");
 }
}
